.radio-hidden:checked + .option-label {
    border-color: #000;
    background: #000;
    color: #fff;
}

.option-text {
    display: block;
    font-weight: 600;
}

.option-price {
    display: block;
    font-size: 0.9em;
    margin-top: 4px;
}


.form-ajax-cart-donation{
    display: flex;
    gap: 16px;
    padding: 30px 0;
}
.form-ajax-cart-donation .blockimg{
    width: 112px;
    text-align: center;
}
.form-ajax-cart-donation .blockimg > img{
    width: 75px;
    object-fit: cover;
    object-position: center;
}
.form-ajax-cart-donation .blockaddcart{
    display: flex;
    flex-direction: column;
    gap: 13px;
    align-items: start;
    width: calc(100% - 120px);
    overflow: hidden;
}
.form-ajax-cart-donation h4{
    font-size: 18px;
    margin: 0;
    text-align: left;
}
.form-ajax-cart-donation p{
