/* ── https://www.pierreherme.com/static/version1783754189/frontend/PierreHerme/PierreHermeTheme/en_US/Andafter_CmsWidgets/css/hero.css ── */
.herounderheader .autopromo-wrapper,
.herounderheader .breadcrumbs{
    display: none !important;
}
.newthemehp{
    position: relative;
    margin-bottom: 20px;
}
.newthemehp img,
.newthemehp video{
    width: 100%;
    object-fit: cover;
    height: 100%;
    object-position: top center;
}

.newthemehp .textbanner{
    position: absolute;
}
.newthemehp .textbanner *{
    color: #fff;
}
.newthemehp .textbanner .pastille{
    padding: 4px 8px;
    background: rgba(156, 181, 226, 0.3);
    backdrop-filter: blur(8px);
    border-radius: 4px;
    font-weight: 900;
    font-size: 12px;
    margin-bottom: 24px;
    display: inline-block;
}
.newthemehp .textbanner .titleh1{
    font-weight: 700;
    font-size: 60px;
    text-transform: uppercase;
    margin-bottom: 8px;
}
@media screen and (max-width: 768px){
    .newthemehp .textbanner .titleh1{
        font-size: 40px;
    }
}
.newthemehp .textbanner .titleh1{

}
.newthemehp .textbanner p{
    font-weight: 400;
    font-size: 16px;
}
.newthemehp .textbanner a{
    margin-top: 24px;
    border-bottom: 1.5px solid #FFFFFF;
    text-transform: uppercase;
    font-weight: bold;
}
@media screen and (max-width: 650px){
    .herounderheader .autopromo-wrapper{
        position: fixed;
        top: 0;
    }
    .herounderheader .ammenu-header-container.page-header{
        border: none;
    }
    .newthemehp .imagemobile,
    .newthemehp .video{
        height: 400px;
    }
    .imagedesktop{
        display: none;
    }
    .newthemehp .textbanner{
        top: auto;
        bottom: 30px;
        margin-left: 20px;
        margin-right: 20px;
        max-width: 100%;
    }
}
@media screen and (min-width: 651px){
    .herounderheader .header.content .header-container-settings .switcher .dropdown,
    .herounderheader .header.content .header-container-settings .switcher .dropdown:hover{
        color: #fff;
    }
    .herounderheader #ammenu-header-container{
        z-index: 1000;
    }
    .herounderheader .sidebar-account{
        z-index: 1001;
    }
    .herounderheader .navigation{
        max-width: 100%;
    }
    .herounderheader .ammenu-nav-sections.-topmenu .ammenu-submenu-wrapper{
        width: 100% !important;
    }
    .herounderheader .navigation .ammenu-submenu-wrapper > *{
        max-width: 1200px;
        margin: 0 auto;
    }
    .herounderheader .header.content .menu-sup,
    .herounderheader .header.content .header-container-settings{
        z-index: 1;
    }
    .herounderheader .nav-sections:not(.sticky):not(.active) .ammenu-nav-sections,
    .herounderheader .nav-sections:not(.sticky):not(.active) .navigation,
    .herounderheader .breadcrumbs{
        background: transparent;
    }
    .herounderheader .ammenu-header-container,
    .herounderheader .nav-sections{
        transition: none;
    }
    .herounderheader .nav-sections{
        margin: 0;
        padding-top: 10px;
    }
    .sections.nav-sections.active{
        background-color: #fff;
        margin-top: 0;
        padding-top: 15px;
    }
    .herounderheader .ammenu-header-container.page-header:not(.sticky):not(.active),
    .herounderheader .nav-sections:not(.sticky):not(.active){
        z-index: 1;
        background: #fff3;
    }
    .herounderheader .navigation .level0:hover::after {
        left: calc(100% - 10px);
    }
    .herounderheader .ammenu-header-container:not(.sticky):not(.active) .header.content .logo i,
    .herounderheader .ammenu-header-container:not(.sticky):not(.active) .minicart-wrapper .action.showcart::before,
    .herounderheader .ammenu-header-container:not(.sticky):not(.active) .header.content .menu-sup a,
    .herounderheader .ammenu-header-container:not(.sticky):not(.active) .header.content .header-container-settings i,
    .herounderheader .nav-sections:not(.sticky):not(.active) ul li.level0 > a,
    .herounderheader .nav-sections:not(.sticky):not(.active) ul li.level0 > a span{
        color: #fff;
    }
    .herounderheader .ammenu-button.-hamburger.burger span, .burger span{
        background-color: #fff;
    }
    .newthemehp.under-header{
        margin-top: -200px;
    }
    .newthemehp .imagedesktop,
    .newthemehp .video{
        height: calc(100vh + 30px);
    }
    .newthemehp img {
        height: 100%;
        max-width: inherit;
    }
    .imagemobile{
        display: none;
    }
    .newthemehp .textbanner{
        top: 50%;
        transform: translateY(-50%);
        margin-left: 35px;
        margin-right: 45px;
        max-width: 680px;
    }
}


/* ── https://www.pierreherme.com/static/version1783754189/frontend/PierreHerme/PierreHermeTheme/en_US/Andafter_CmsWidgets/css/h1title.css ── */
h1.widget-title{
    text-transform: uppercase;
    font-family: FuturaLight,Helvetica,sans-serif;
    font-size: 26px;
    text-align: center;
    margin-bottom: 30px;
}


/* ── https://www.pierreherme.com/static/version1783754189/frontend/PierreHerme/PierreHermeTheme/en_US/Andafter_CmsWidgets/css/gridimages.css ── */
.dynamic-blocks-widget{
    display: flex;
    flex-direction: row;
    gap: 20px;
    margin-bottom: 20px;
}
.dynamic-block-item{
    position: relative;
    width: 100%;
}
.dynamic-block-item img{
    width: 100%;
}
.dynamic-block-item h2{
    position: absolute;
    bottom: 20px;
    left: 20px;
    font-family:FuturaHeavy,Helvetica,sans-serif;
    font-weight: 600;
    font-size: 20px;
    color: #FFFFFF;
}

@media screen and (max-width: 800px){
    .dynamic-blocks-widget{
        flex-direction: column;
    }
}


